import { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

export function cacheMiddleware(
  redis: Redis,
  ttlSeconds: number = 300
) {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (req.method !== 'GET') return next();

    const cacheKey = `http:${req.originalUrl}`;
    const cached = await redis.get(cacheKey);

    if (cached) {
      res.setHeader('X-Cache', 'HIT');
      return res.json(JSON.parse(cached));
    }

    // Capture response body
    const originalJson = res.json.bind(res);
    const chunks: Buffer[] = [];

    res.json = (body: unknown) => {
      chunks.push(Buffer.from(JSON.stringify(body)));
      return originalJson(body);
    };

    res.on('finish', async () => {
      if (res.statusCode < 400) {
        const body = JSON.parse(chunks.join('').toString());
        await redis.set(cacheKey, JSON.stringify(body), 'EX', ttlSeconds);
      }
    });

    res.setHeader('X-Cache', 'MISS');
    next();
  };
}

import express from 'express';
import { cacheMiddleware } from './cache-middleware';
import Redis from 'ioredis';

const app = express();
const redis = new Redis();

// Public routes — cache aggressively
app.get('/api/products', cacheMiddleware(redis, 600));
app.get('/api/products/:id', cacheMiddleware(redis, 600));

// User-specific routes — no caching
app.get('/api/me', (req, res) => {
  res.json({ userId: req.user.id });
});

